import SwiftUI

struct ConversationDynamicsScreen: View { let d = SampleData.dynamics
    var body: some View { NavigationStack { ZStack { SecondTheme.background.ignoresSafeArea(); ScrollView { VStack(spacing:16) { ScreenHeader(title:"Conversation Dynamics", subtitle:"Turn-taking and interaction flow"); AppCard(title:"Speaking vs Listening") { HStack { VStack(alignment:.leading) { Text("You spoke").font(.caption).foregroundStyle(SecondTheme.secondaryText); Text("\(Int(d.userSpeakingPercent))%").font(.largeTitle).bold().foregroundStyle(SecondTheme.heartRate) }; Spacer(); RingPercentView(percent:d.userSpeakingPercent/100); Spacer(); VStack(alignment:.trailing) { Text("They spoke").font(.caption).foregroundStyle(SecondTheme.secondaryText); Text("\(Int(d.otherSpeakingPercent))%").font(.largeTitle).bold().foregroundStyle(SecondTheme.respiration) } } }.padding(.horizontal); AppCard(title:"Turn Taking") { HStack { SignalBadge(icon:"arrow.left.arrow.right", title:"Turns", value:"\(d.turnsTaken)", color:SecondTheme.heartRate); Spacer(); SignalBadge(icon:"timer", title:"Avg Turn", value:String(format:"%.1fs", d.averageTurnLength), color:SecondTheme.amber); Spacer(); SignalBadge(icon:"exclamationmark.triangle", title:"Interruptions", value:"\(d.interruptions)", color:SecondTheme.gold) } }.padding(.horizontal); AppCard(title:"Conversation Flow") { VStack(spacing:10) { HStack { Text("You"); Spacer(); Text("Them") }.font(.caption).foregroundStyle(SecondTheme.secondaryText); GeometryReader { g in ZStack(alignment:.leading) { Capsule().fill(SecondTheme.border); Capsule().fill(SecondTheme.heartRate).frame(width:g.size.width*0.58) } }.frame(height:10); MetricRow(label:"Dominance index", value:String(format:"%.2f", d.dominanceIndex)) } }.padding(.horizontal); AppCard(title:"Physiological Activation Overlay") { VStack { MiniLineChart(values:SampleData.biometricSamples.compactMap{$0.heartRate}, color:SecondTheme.heartRate); MiniLineChart(values:SampleData.biometricSamples.compactMap{$0.respiration}, color:SecondTheme.respiration) } }.padding(.horizontal) }.padding(.bottom,24) } } } }
}
struct RingPercentView: View { let percent:Double
    var body: some View { ZStack { Circle().stroke(SecondTheme.border, lineWidth:16); Circle().trim(from:0,to:percent).stroke(SecondTheme.heartRate, style:StrokeStyle(lineWidth:16,lineCap:.round)).rotationEffect(.degrees(-90)); VStack { Text("Total").font(.caption2).foregroundStyle(SecondTheme.secondaryText); Text("27m").font(.headline).bold() } }.frame(width:110,height:110) }
}
